-- 198: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_198_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_198_guard;
INSERT INTO _migration_198_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_021' AND NOT (q.topic_id IS 'topic_was_basketry_b004_5' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How is visual balance achieved in an asymmetrical basket decoration?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Give the shapes similar size and colour without considering visual weight","B. Use mirrored motifs because asymmetrical layouts usually lack balance","C. Different elements are arranged so their visual weights feel stable without mirroring","D. Place the largest dark motif at one edge without a countering element"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Asymmetrical balance can combine unequal shapes, colours or textures while distributing their visual emphasis so the finished composition still feels stable and intentional. Therefore the correct answer is C: Different elements are arranged so their visual weights feel stable without mirroring.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_021' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_198_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_022' AND NOT (q.topic_id IS 'topic_was_basketry_b004_5' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What design effect is produced by repeating a coloured weaving unit at regular intervals?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Harmony created by using closely related colours without a repeated interval","B. Proportion created by changing the handle size relative to the body","C. Rhythm that guides the eye around the form","D. Emphasis created by one isolated contrasting motif at the centre"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Regular repetition establishes an expected visual beat, and carefully varied spacing or colour can strengthen movement without undermining the functional woven structure. Therefore the correct answer is C: Rhythm that guides the eye around the form.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_022' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_198_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_023' AND NOT (q.topic_id IS 'topic_was_basketry_b004_5' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should the scale of a handle be considered in relation to the basket body?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Use one standard handle dimension for baskets with different carrying purposes","B. Choose the shortest handle because reduced span is the main capacity requirement","C. Judge the handle only by colour because scale does not affect grip","D. Proportion affects both visual unity and comfortable functional use"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A handle that relates to the body’s size and load appears integrated and provides suitable clearance and grip; poor proportion can impair both appearance and usability. Therefore the correct answer is D: Proportion affects both visual unity and comfortable functional use.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_023' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_198_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_024' AND NOT (q.topic_id IS 'topic_was_basketry_b004_5' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which colour decision is most likely to produce a controlled harmonious pattern?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Choose each colour after its strip is woven so no full scheme is considered","B. Select a limited related palette and repeat it according to a plan","C. Combine different dye batches without sampling because their labels match","D. Use many high-intensity colours in equal amounts to create harmony"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A planned limited palette lets natural and dyed materials relate coherently, while deliberate repetition makes colour changes readable as part of the design rather than accidental repairs. Therefore the correct answer is B: Select a limited related palette and repeat it according to a plan.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_024' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_021', 'topic_was_basketry_b004_5', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'How is visual balance achieved in an asymmetrical basket decoration?', 'multiple_choice', NULL, '["A. Give the shapes similar size and colour without considering visual weight","B. Use mirrored motifs because asymmetrical layouts usually lack balance","C. Different elements are arranged so their visual weights feel stable without mirroring","D. Place the largest dark motif at one edge without a countering element"]', 'C', 'Asymmetrical balance can combine unequal shapes, colours or textures while distributing their visual emphasis so the finished composition still feels stable and intentional. Therefore the correct answer is C: Different elements are arranged so their visual weights feel stable without mirroring.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_5', 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_022', 'topic_was_basketry_b004_5', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What design effect is produced by repeating a coloured weaving unit at regular intervals?', 'multiple_choice', NULL, '["A. Harmony created by using closely related colours without a repeated interval","B. Proportion created by changing the handle size relative to the body","C. Rhythm that guides the eye around the form","D. Emphasis created by one isolated contrasting motif at the centre"]', 'C', 'Regular repetition establishes an expected visual beat, and carefully varied spacing or colour can strengthen movement without undermining the functional woven structure. Therefore the correct answer is C: Rhythm that guides the eye around the form.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_5', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_023', 'topic_was_basketry_b004_5', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Why should the scale of a handle be considered in relation to the basket body?', 'multiple_choice', NULL, '["A. Use one standard handle dimension for baskets with different carrying purposes","B. Choose the shortest handle because reduced span is the main capacity requirement","C. Judge the handle only by colour because scale does not affect grip","D. Proportion affects both visual unity and comfortable functional use"]', 'D', 'A handle that relates to the body’s size and load appears integrated and provides suitable clearance and grip; poor proportion can impair both appearance and usability. Therefore the correct answer is D: Proportion affects both visual unity and comfortable functional use.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_5', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_024', 'topic_was_basketry_b004_5', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which colour decision is most likely to produce a controlled harmonious pattern?', 'multiple_choice', NULL, '["A. Choose each colour after its strip is woven so no full scheme is considered","B. Select a limited related palette and repeat it according to a plan","C. Combine different dye batches without sampling because their labels match","D. Use many high-intensity colours in equal amounts to create harmony"]', 'B', 'A planned limited palette lets natural and dyed materials relate coherently, while deliberate repetition makes colour changes readable as part of the design rather than accidental repairs. Therefore the correct answer is B: Select a limited related palette and repeat it according to a plan.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_5', 'Identify', 'AO3', NULL, NULL, 'board_waec');
